																	"*": {
																		"CartSummaryHeader__": {
																			"type": "HTML",
																			"data": false,
																			"stamp": 49,
																			"options": {
																				"label": "CartSummary",
																				"htmlContent": "<div>\n\t<input id=\"onChange\" type=\"hidden\" style=\"display:none;\" onclick=\"SetValue(event);\">\n\t<div class=\"cart-header\">\n\t\t<div class=\"cart-icon\">\n\t\t\t<span id=\"cart-badge\" class=\"cart-badge\">0</span>\n\t\t\t<img src=\"resource.file?level=account&name=Purchasing_Cart.svg&type=TYPE_IMAGE\"></img>\n\t\t</div>\n\t\t<div id=\"cart-label\" class=\"cart-label text-size-M text-color-color5\">Cart:</div>\n\t\t<div class=\"cart-amount\">\n\t\t\t<div id=\"cart-amount\" class=\"amount text-color-color1\">0</div>\n\t\t\t<div id=\"cart-currency\" class=\"cart-currency  text-color-color1\">USD</div>\n\t\t</div>\n\t</div>\n\t<hr class=\"splitter\">\n\n\t<script type=\"text/javascript\">\n\t\twindow.postMessage({ eventName: \"OnChange\", control: \"CartSummaryHeader__\" }, document.location.origin);\n\t\tvar elementcartbadge = document.getElementById(\"cart-badge\");\n\t\tvar elementcartamount = document.getElementById(\"cart-amount\");\n\t\tvar elementcartcurrency = document.getElementById(\"cart-currency\");\n\t\tvar elementcartlabel = document.getElementById(\"cart-label\");\n\t\tfunction SetValue(evt)\n\t\t{\n\t\t\telementcartbadge.innerText = evt.totalQuantity;\n\t\t\telementcartamount.innerText = evt.totalPrice;\n\t\t\telementcartcurrency.innerText = evt.currency;\n\t\t\telementcartlabel.innerText = evt.label;\n\t\t}\n\t</script>\n</div>",
																				"css": ".cart-header {\n\tdisplay: flex;\n\talign-items: center;\n\tpadding-left: 15px;\n\tpadding-right: 15px;\n}\n\n.cart-icon {\n\tposition: relative;\n\tflex-grow: 0;\n\tflex-basis: 15%;\n}\n\n.cart-badge {\n\tposition: absolute;\n\ttop: -2px;\n\tleft: 15px;\n\tdisplay: flex;\n\tjustify-content: center;\n\talign-items: center;\n\tflex-direction: column; /* IE */\n\tpadding: 4px 11px;\n\twidth: 0px;\n\tbackground: #F12938;\n\tborder-radius: 50%;\n\tfont-family: 'Roboto Bold', sans-serif;\n\tfont-size: 10px;\n\tcolor: white;\n}\n\n.cart-label {\n\tflex-grow: 0;\n\tflex-basis: 15%;\n\tfont-family: 'Roboto Bold', sans-serif;\n}\n\n.cart-amount {\n\tflex-grow: 1;\n    text-align: right;\n}\n\n.amount {\n\tposition: relative;\n\tdisplay: inline-block;\n\tfont-size: 20px;\n\tfont-family: 'Roboto Bold', sans-serif;\n}\n\n.cart-currency {\n\tposition: relative;\n\tdisplay: inline-block;\n\tfont-size: 16px;\n\tfont-family: 'Roboto Bold', sans-serif;\n}\n\n.splitter {\n\tborder-width: 0;\n\tborder-top: 1px solid rgb(166, 176, 185);\n}",
